
-- Insert 18 missing African dishes with full cultural context
WITH new_dishes AS (
  INSERT INTO public.dishes (name, country, continent, region, slug, summary, cultural_significance, original_name_native, primary_tribe_ethnicity, phonetic_spelling) VALUES
  ('Brik', 'Tunisia', 'Africa', 'North Africa', 'brik-tunisia',
    'Crispy thin pastry stuffed with a runny egg, tuna, capers, parsley and harissa, fried until golden.',
    'Brik traces back to Ottoman-era Tunisia where Andalusian and Turkish pastry traditions met local Berber cooking. It is the iconic opener of Tunisian Ramadan iftars and weddings — the unbroken yolk symbolising prosperity. Eating it without spilling the yolk is a small national rite of passage.',
    'بريك', 'Tunisian Arab-Berber', 'breek'),
  ('Ahriche', 'Algeria', 'Africa', 'North Africa', 'ahriche-algeria',
    'Slow-grilled lamb tripe and offal skewers seasoned with cumin, garlic and chilli, a celebratory Eid dish.',
    'Ahriche (Aïd) is prepared the day after Eid al-Adha in Algeria, particularly in Kabyle and Constantinois homes, using the offal of the sacrificed sheep so nothing is wasted — a Berber principle of zero-waste cooking that predates Islam.',
    'أهريش', 'Kabyle Berber', 'ah-reesh'),
  ('Briouat', 'Morocco', 'Africa', 'North Africa', 'briouat-morocco',
    'Triangular warqa-pastry parcels filled with sweet almond paste perfumed with orange-blossom water, fried then dipped in honey.',
    'Briouats are a cornerstone of Moroccan wedding diffas and Ramadan tables. The almond-honey version reflects the Andalusian heritage that flowed into Fez after 1492; the savoury meat version mirrors the same parcel found in the Maghreb-wide pastilla family.',
    'بريوات', 'Moroccan Arab-Andalusian', 'bree-wat'),
  ('Pounded Yam with Ofe Nsala', 'Nigeria', 'Africa', 'West Africa', 'pounded-yam-ofe-nsala-nigeria',
    'Smooth, elastic pounded yam (iyán) served with Ofe Nsala — an Igbo white pepper soup of catfish and utazi leaves.',
    'Pounded yam is the ceremonial staple of the Yoruba and Igbo, traditionally produced in a wooden mortar (odó) in a rhythmic two-person pounding. Ofe Nsala is the soup served to new mothers in Igboland to restore strength after childbirth.',
    'Iyán àti Ofe Nsala', 'Yoruba / Igbo', 'ee-yahn / oh-feh n-sah-lah'),
  ('Garri', 'Nigeria', 'Africa', 'West Africa', 'garri-nigeria',
    'Fermented, roasted cassava granules eaten as eba (with hot water) or soaked cold with sugar, milk and groundnuts.',
    'Garri sustained millions during the Nigerian Civil War and remains the most democratic food in West Africa — eaten by farmers and presidents alike. Its fermentation method was perfected by Yoruba women in the 19th century, transforming a poisonous tuber into a national staple.',
    'Gaari', 'Yoruba / Igbo / Edo', 'gah-ree'),
  ('Nkwobi', 'Nigeria', 'Africa', 'West Africa', 'nkwobi-nigeria',
    'Spicy cow foot delicacy in a thick palm-oil and potash sauce, finished with utazi leaves and onion, served in a wooden bowl.',
    'Nkwobi originated in the bukas and palm-wine bars of Igboland (Eastern Nigeria) in the mid-20th century. It is a brotherhood food — shared from one wooden bowl with palm wine, traditionally eaten by Igbo men gathered to settle disputes or celebrate.',
    'Nkwọbi', 'Igbo', 'n-kwoh-bee'),
  ('Matoke', 'Uganda', 'Africa', 'East Africa', 'matoke-uganda',
    'East African Highland cooking-banana steamed in its own leaves until soft, mashed and served with groundnut or beef stew.',
    'Matoke is the cultural and spiritual staple of the Baganda — a kingdom whose name literally means "people of the matoke". A Muganda meal without matoke is considered no meal at all; it is steamed in banana leaves at every wedding, funeral and naming ceremony.',
    'Matooke', 'Baganda', 'mah-toh-keh'),
  ('Kuku Paka', 'Kenya', 'Africa', 'East Africa', 'kuku-paka-kenya',
    'Coastal Swahili chargrilled chicken simmered in a coconut, lime, turmeric and green-chilli curry.',
    'Kuku Paka is the signature dish of the Swahili coast (Mombasa, Lamu, Zanzibar), born from the 19th-century meeting of Bantu, Arab, Indian and Portuguese traders. The dual cooking — flame then coconut — embodies the coast''s monsoon-trade identity.',
    'Kuku Paka', 'Swahili', 'koo-koo pah-kah'),
  ('Gored Gored', 'Ethiopia', 'Africa', 'East Africa', 'gored-gored-ethiopia',
    'Cubes of raw lean beef tossed in awaze (chilli paste), niter kibbeh spiced butter and mitmita, eaten with injera.',
    'Gored gored is the warrior dish of the Ethiopian highlands, historically eaten by Amhara and Tigrayan soldiers before battle for instant strength. It is still served at Meskel and Genna feasts and considered a delicacy of bravery.',
    'ጎረድ ጎረድ', 'Amhara / Tigray', 'goh-red goh-red'),
  ('Ga''at', 'Ethiopia', 'Africa', 'East Africa', 'gaat-ethiopia',
    'Thick barley or wheat porridge formed into a mound, hollowed at the centre and filled with spiced niter kibbeh and berbere.',
    'Ga''at is the traditional breakfast of pregnant women, new mothers and Orthodox Christian fasters in northern Ethiopia and Eritrea. The central well of spiced butter is a cultural symbol of the womb and nourishment.',
    'ገዓት', 'Tigray / Amhara / Tigrinya', 'guh-aht'),
  ('Ekwang', 'Cameroon', 'Africa', 'Central Africa', 'ekwang-cameroon',
    'Grated cocoyam wrapped in young cocoyam leaves, slow-simmered in palm oil with crayfish, smoked fish and bush pepper.',
    'Ekwang is the prestige dish of the Bakweri and Bakossi people of Southwest Cameroon, prepared for traditional marriages and the Ngondo festival. The patient leaf-wrapping is a communal women''s ritual that can take an entire afternoon.',
    'Ekwang', 'Bakweri / Bakossi', 'eh-kwang'),
  ('Gozo', 'Central African Republic', 'Africa', 'Central Africa', 'gozo-car',
    'Stiff fermented cassava-flour fufu pounded into a smooth dough, served with palm-nut, peanut or smoked-fish sauces.',
    'Gozo is the everyday staple of the Sango and Gbaya peoples of CAR. It is eaten with the right hand, formed into a small ball, dipped into sauce, and never chewed — only swallowed — a custom shared across the Congo basin.',
    'Gozo', 'Sango / Gbaya', 'goh-zoh'),
  ('Braai', 'South Africa', 'Africa', 'Southern Africa', 'braai-south-africa',
    'Open-flame wood/charcoal barbecue of boerewors, lamb chops, sosaties and steak, served with pap and chakalaka.',
    'Braai is South Africa''s unifying national ritual — declared a public holiday (National Braai Day) on Heritage Day, 24 September. Tutu and Mandela both championed it as the one tradition that crosses every cultural line in the country.',
    'Braai', 'Afrikaner / Pan-South African', 'bry'),
  ('Boerewors', 'South Africa', 'Africa', 'Southern Africa', 'boerewors-south-africa',
    'Coiled farmer''s sausage of beef and pork seasoned with coriander, clove, nutmeg and vinegar, grilled over coals.',
    'Boerewors descends from the 17th-century Dutch verse worst, perfected by Voortrekker farmers on the Great Trek when they needed shelf-stable spiced meat. Government regulation defines its minimum 90% meat content — making it a legally protected South African heritage food.',
    'Boerewors', 'Afrikaner', 'boo-rah-vors'),
  ('Biltong', 'South Africa', 'Africa', 'Southern Africa', 'biltong-south-africa',
    'Air-dried, vinegar- and coriander-cured strips of beef or game (kudu, springbok), sliced thin and eaten as a snack.',
    'Biltong was developed by the Khoikhoi and refined by the Voortrekkers in the 1830s, who needed protein that survived ox-wagon journeys across the veld. Unlike American jerky, biltong is air-cured, never smoked — preserving the deeper, winier flavour.',
    'Biltong', 'Khoikhoi / Afrikaner', 'bill-tong'),
  ('Vetkoek', 'South Africa', 'Africa', 'Southern Africa', 'vetkoek-south-africa',
    'Deep-fried yeasted dough cushions, split and filled with curried mince, apricot jam, or syrup and cheese.',
    'Vetkoek (literally "fat cake") is a Voortrekker-era frontier bread cooked in a cast-iron potjie when ovens were unavailable. Today it is the staple township breakfast across South Africa, sold from kerbside stalls before dawn.',
    'Vetkoek', 'Afrikaner / Township', 'fet-cook'),
  ('Melktert', 'South Africa', 'Africa', 'Southern Africa', 'melktert-south-africa',
    'Silky cinnamon-dusted milk-and-egg custard tart in a sweet shortcrust shell, served chilled.',
    'Melktert evolved in 17th-century Cape Dutch kitchens from the Dutch mattentaart, adapted with Cape spice-route cinnamon. It is the dessert of every Sunday lunch and Heritage Day, and a finalist for South Africa''s most-loved bake.',
    'Melktert', 'Cape Dutch / Afrikaner', 'melk-tairt'),
  ('Kapenta with Sadza', 'Zambia', 'Africa', 'Southern Africa', 'kapenta-sadza-zambia',
    'Sun-dried Lake Tanganyika sardines (kapenta) fried with tomato and onion, served with stiff maize-meal sadza.',
    'Kapenta fishing on Lakes Tanganyika and Kariba is a cultural and economic pillar of Zambia and Zimbabwe — boats fish at night using paraffin lamps. The dish is the most affordable source of protein for millions and a staple of the Tonga and Bemba peoples.',
    'Kapenta ne Sadza', 'Tonga / Bemba', 'kah-pen-tah neh sahd-zah')
  ON CONFLICT (name, country) DO NOTHING
  RETURNING id, slug, name, country
)
INSERT INTO public.recipes (
  dish_id, name, slug, country, continent, summary, history, brief_description,
  ingredients, steps, image_url, prep_time, cook_time, prep_time_minutes, cook_time_minutes,
  servings, difficulty, category, cuisine_type, tags, is_african, is_verified_authentic
)
SELECT
  d.id, d.name, d.slug, d.country, 'Africa',
  m.summary, m.history, m.summary,
  m.ingredients::jsonb, m.steps::jsonb, m.image_url,
  m.prep, m.cook, m.prep, m.cook,
  m.servings, m.difficulty, m.category, m.cuisine, m.tags::text[], true, true
FROM new_dishes d
JOIN (VALUES
  ('brik-tunisia',
    'Crispy Tunisian pastry parcel with a runny yolk, tuna and harissa.',
    'Documented since the 16th century in Tunis, brik fuses Andalusian warqa pastry with Mediterranean tuna and Berber harissa. It is the unmissable starter of Ramadan iftar tables in Tunisia.',
    '["4 sheets malsouka (warqa) or thin filo","4 small eggs","1 can tuna in oil, drained","2 tbsp capers","2 tbsp chopped parsley","1 tsp harissa","1 small onion, finely chopped","Salt, black pepper","Vegetable oil for frying","1 lemon, wedged"]',
    '["Mix tuna, capers, parsley, onion and harissa in a bowl; season.","Lay one malsouka sheet flat. Place a quarter of the tuna mix in the centre, making a small well.","Crack one egg into the well. Salt the yolk lightly.","Fold the pastry into a triangle, sealing the edges with a wet finger.","Slide carefully into 180°C oil and fry 60–90 seconds per side until golden, keeping the yolk runny.","Drain on paper towel, serve immediately with lemon."]',
    'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=800&q=80',
    20, 10, 4, 'Medium', 'Appetizer', 'Tunisian',
    '{"Tunisia","North Africa","Ramadan","Pastry","Egg"}'),
  ('ahriche-algeria',
    'Algerian Eid grilled lamb-offal skewers seasoned with cumin and chilli.',
    'Prepared the day after Aïd el-Kebir from the offal of the sacrificed sheep, ahriche is a Kabyle Berber tradition of waste-free cooking.',
    '["500g lamb tripe, cleaned","250g lamb liver","250g lamb heart","250g caul fat (crépine)","2 tsp ground cumin","1 tsp paprika","1 tsp chilli","4 garlic cloves, crushed","3 tbsp olive oil","Salt, pepper","Skewers"]',
    '["Boil tripe 45 min until tender; cool and cut in 2cm pieces.","Cube heart and liver. Toss all offal with garlic, spices, salt, pepper and olive oil.","Wrap each skewer of offal pieces with a strip of caul fat to baste during cooking.","Grill over hot charcoal 8–10 minutes, turning often, until caul fat melts and meat chars.","Serve with bread, harissa and lemon."]',
    'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?w=800&q=80',
    30, 60, 6, 'Hard', 'Main', 'Algerian',
    '{"Algeria","North Africa","Eid","Grill","Offal","Berber"}'),
  ('briouat-morocco',
    'Moroccan triangular almond-honey pastries scented with orange-blossom water.',
    'A jewel of Fassi cuisine since the Andalusian exodus of 1492, briouats grace every Moroccan wedding diffa and Ramadan table.',
    '["20 sheets warqa or filo pastry","300g blanched almonds","150g icing sugar","2 tbsp orange blossom water","1 tsp cinnamon","50g butter, melted","1 egg yolk","300g honey","Vegetable oil for frying"]',
    '["Toast almonds at 180°C for 8 min, cool, then grind with sugar, cinnamon, butter and orange blossom water into a paste.","Cut warqa into long strips ~8cm wide. Place a teaspoon of paste at one end.","Fold into a triangle by alternating diagonal folds along the strip; seal with egg yolk.","Fry in 170°C oil 1–2 min until golden brown.","Warm honey gently. Dip hot briouats in honey for 30 seconds; lift out, drain on a rack and cool."]',
    'https://images.unsplash.com/photo-1606471191009-63994c53433b?w=800&q=80',
    45, 25, 8, 'Medium', 'Dessert', 'Moroccan',
    '{"Morocco","North Africa","Pastry","Honey","Almond","Ramadan"}'),
  ('pounded-yam-ofe-nsala-nigeria',
    'Smooth pounded yam served with Igbo Ofe Nsala white pepper catfish soup.',
    'A ceremonial staple of the Yoruba and Igbo, with Ofe Nsala traditionally served to new mothers in Igboland.',
    '["1.5 kg white yam, peeled and cubed","1 large catfish, cleaned and cut","2 tbsp ground utazi leaves","2 tbsp ofor (yam-flour thickener)","1 tbsp ground crayfish","2 tbsp ground ehu (calabash nutmeg)","1 stock cube","1 onion, sliced","2 scotch bonnets, ground","Salt to taste"]',
    '["Boil yam cubes 25 min until very soft. Pound hot in a mortar (or blend) until smooth and stretchy.","Season catfish with salt, onion and stock cube; simmer in 1 L water 10 min.","Add ehu, crayfish and scotch bonnet; simmer 5 min.","Whisk ofor with water and stir into the soup until thickened and glossy.","Add utazi leaves, simmer 2 min, taste for salt.","Serve molded pounded yam alongside the soup; eat with fingers, dipping balls of yam."]',
    'https://images.unsplash.com/photo-1562967914-608f82629710?w=800&q=80',
    25, 45, 4, 'Medium', 'Main', 'Nigerian',
    '{"Nigeria","West Africa","Igbo","Yoruba","Soup","Yam"}'),
  ('garri-nigeria',
    'Fermented roasted cassava granules eaten as eba or as a cold drink with milk and sugar.',
    'Garri sustained the Biafran resistance and remains the most democratic food in West Africa.',
    '["2 cups garri (white or yellow)","Cold water or hot water","Sugar, roasted groundnuts (peanuts)","Powdered milk","Optional: ice cubes"]',
    '["For drinking garri: place 1 cup garri in a bowl. Add cold water until granules float and swell.","Add 2 tbsp sugar, 2 tbsp powdered milk, a handful of roasted peanuts; stir.","For eba: bring 1 cup water to boil, remove from heat, pour in 1.5 cups garri and let sit 1 minute.","Stir vigorously with a wooden spatula until smooth and stretchy. Mold into a ball.","Serve eba with egusi, okra or vegetable soup."]',
    'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=800&q=80',
    5, 5, 4, 'Easy', 'Staple', 'West African',
    '{"Nigeria","West Africa","Cassava","Staple","Quick"}'),
  ('nkwobi-nigeria',
    'Spicy Igbo cow foot in palm-oil sauce served in a traditional wooden bowl.',
    'Born in the palm-wine bars of Eastern Nigeria, nkwobi is a brotherhood dish shared from one wooden bowl.',
    '["1.5 kg cow foot, cut into pieces","1 tsp edible potash (akanwu) dissolved in 50 ml water","150 ml palm oil","2 tbsp ground crayfish","1 tbsp ehu (calabash nutmeg), ground","2 scotch bonnets, ground","2 tbsp utazi leaves, sliced thin","1 onion, sliced","1 stock cube","Salt"]',
    '["Boil cow foot with onion, stock cube and salt 1.5–2 hours until very tender; reserve a little stock.","In a clean pot, mix palm oil with potash water — it will turn yellow and creamy.","Stir in crayfish, ehu and scotch bonnet; add 4 tbsp reserved stock.","Fold in cow foot pieces and warm through over low heat 5 min, coating every piece.","Transfer to a wooden mortar bowl, top with utazi leaves and onion rings.","Serve with chilled palm wine or stout."]',
    'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&q=80',
    20, 120, 4, 'Hard', 'Main', 'Nigerian',
    '{"Nigeria","West Africa","Igbo","Palm Oil","Spicy"}'),
  ('matoke-uganda',
    'Steamed Ugandan green bananas mashed and served with groundnut sauce.',
    'The cultural and spiritual staple of the Baganda kingdom, steamed in banana leaves at every ceremony.',
    '["8 green East African Highland bananas (matooke)","Banana leaves for wrapping","1 onion, chopped","2 tomatoes, chopped","100 g groundnut paste","1 tsp curry powder","Salt","500 ml water"]',
    '["Peel matoke under running water (the sap stains). Wrap tightly in banana leaves.","Place wrapped matoke in a pot with a little water, cover and steam 1.5 hours.","Meanwhile sauté onion and tomato 5 min; whisk in groundnut paste with 250 ml water and curry powder. Simmer 10 min into a smooth sauce; season.","Unwrap steamed matoke and mash inside the leaves until smooth and pale yellow.","Serve mounds of mashed matoke with groundnut sauce poured over."]',
    'https://images.unsplash.com/photo-1604329760661-e71dc83f8f26?w=800&q=80',
    20, 90, 6, 'Medium', 'Main', 'Ugandan',
    '{"Uganda","East Africa","Baganda","Banana","Steamed"}'),
  ('kuku-paka-kenya',
    'Swahili coast chargrilled chicken in coconut, lime and turmeric curry.',
    'A signature of the Mombasa-Lamu-Zanzibar coast, born from Bantu, Arab, Indian and Portuguese trade.',
    '["1 whole chicken, jointed","400 ml coconut milk","2 tomatoes, chopped","2 onions, sliced","4 garlic cloves","2cm ginger","2 green chillies","1 tsp turmeric","1 tsp cumin","Juice of 2 limes","2 hard-boiled eggs","Coriander to garnish","Salt"]',
    '["Marinate chicken with half the lime juice, salt and turmeric 30 min; grill over charcoal 15 min until charred but not cooked through.","Sauté onion 8 min; add blended garlic, ginger, chilli and tomato; cook 5 min.","Add cumin, remaining turmeric, then coconut milk; simmer 5 min.","Add grilled chicken pieces; simmer gently 20 min until tender and sauce thickens.","Halve hard-boiled eggs and add to the pan; finish with remaining lime juice and coriander.","Serve with coconut rice or chapati."]',
    'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?w=800&q=80',
    40, 45, 4, 'Medium', 'Main', 'Kenyan / Swahili',
    '{"Kenya","East Africa","Swahili","Coconut","Curry","Chicken"}'),
  ('gored-gored-ethiopia',
    'Ethiopian raw beef cubes tossed in spiced butter and awaze chilli paste.',
    'A warrior dish of the Amhara and Tigray highlands, served at Meskel and Genna feasts.',
    '["500 g very fresh lean beef tenderloin","3 tbsp niter kibbeh (Ethiopian spiced butter)","2 tbsp awaze (berbere–wine chilli paste)","1 tsp mitmita spice","1/2 tsp ground cardamom","Salt","Injera to serve"]',
    '["Use only freshly butchered, cold tenderloin. Trim every trace of sinew.","Cut beef into 1.5 cm cubes against the grain.","Melt niter kibbeh gently; do not brown.","Toss beef cubes with warm niter kibbeh, awaze, mitmita, cardamom and salt; serve immediately.","Eat scooped onto torn pieces of injera."]',
    'https://images.unsplash.com/photo-1567337710282-00832b415979?w=800&q=80',
    15, 0, 4, 'Easy', 'Main', 'Ethiopian',
    '{"Ethiopia","East Africa","Raw","Beef","Berbere","Festive"}'),
  ('gaat-ethiopia',
    'Thick highland barley porridge with a well of spiced butter and berbere.',
    'The traditional postpartum and fasting breakfast of northern Ethiopia and Eritrea.',
    '["2 cups barley flour (or wheat)","4 cups water","1 tsp salt","4 tbsp niter kibbeh","2 tsp berbere","1/2 cup plain yogurt"]',
    '["Bring salted water to a boil. Whisk in barley flour off the heat to avoid lumps.","Return to low heat, stirring constantly with a wooden spoon 12–15 min until very thick and pulling from the pan.","Mound on a plate; press a deep well in the centre with the back of a spoon.","Pour melted niter kibbeh into the well; sprinkle berbere over the butter.","Spoon yogurt around the edges. Eat by scooping outside-in, dipping each spoonful into the spiced butter."]',
    'https://images.unsplash.com/photo-1571197119282-7c4e2c2dba98?w=800&q=80',
    5, 20, 4, 'Easy', 'Breakfast', 'Ethiopian',
    '{"Ethiopia","Eritrea","East Africa","Porridge","Barley","Fasting"}'),
  ('ekwang-cameroon',
    'Cameroonian grated cocoyam wrapped in cocoyam leaves, simmered in spiced palm oil.',
    'The prestige dish of the Bakweri and Bakossi people, prepared for the Ngondo festival.',
    '["1 kg cocoyam (taro), peeled","30 young cocoyam leaves, washed","200 ml red palm oil","200 g smoked fish, flaked","100 g dried crayfish, ground","1 tbsp ground bush pepper","1 onion, blended","2 stock cubes","500 ml water","Salt"]',
    '["Grate cocoyam finely on the small holes of a box grater into a smooth paste; season with salt.","Spread half a teaspoon of paste on each cocoyam leaf and roll tightly into small bundles.","Layer the bundles in a heavy pot with the smoked fish and crayfish.","Whisk palm oil, blended onion, bush pepper and stock cubes with water; pour over the bundles.","Cover and simmer 1 hour without stirring; the leaves dissolve into the sauce.","Gently fold once at the end so the bundles soak in the deep red sauce. Serve hot."]',
    'https://images.unsplash.com/photo-1569058242253-92a9c755a0ec?w=800&q=80',
    45, 60, 6, 'Hard', 'Main', 'Cameroonian',
    '{"Cameroon","Central Africa","Bakweri","Cocoyam","Palm Oil"}'),
  ('gozo-car',
    'Central African fermented cassava-flour fufu eaten with palm-nut or peanut sauce.',
    'The everyday staple of the Sango and Gbaya peoples, eaten by hand across the Congo basin.',
    '["3 cups cassava flour (foufou)","4 cups water","Pinch of salt"]',
    '["Bring 3 cups of water to a rolling boil with a pinch of salt.","Off the heat, sprinkle in half the cassava flour while stirring vigorously with a wooden spatula.","Return to low heat. Add the remaining flour gradually, working the mixture against the side of the pot until smooth, glossy and elastic.","Add a splash more hot water if too stiff; cook 5 min, folding constantly.","Wet your hands and shape into a single mound on a plate.","Serve with palm-nut soup, peanut sauce or smoked fish stew; eat with the right hand."]',
    'https://images.unsplash.com/photo-1604908554049-2096b8b4c1bb?w=800&q=80',
    5, 15, 4, 'Easy', 'Staple', 'Central African',
    '{"CAR","Central Africa","Cassava","Fufu","Staple"}'),
  ('braai-south-africa',
    'South African open-fire barbecue of boerewors, lamb and steak with pap and chakalaka.',
    'A unifying national ritual celebrated on Heritage Day (24 September), endorsed by Archbishop Tutu.',
    '["1 kg boerewors coil","6 lamb chops","4 sirloin steaks","Coarse salt and pepper","1 cup chakalaka","Pap (maize porridge) for serving","Hardwood (kameeldoring or rooikrans) and charcoal","Mealies (corn) optional"]',
    '["Build a wood fire and burn down to grey-white embers — never start cooking on flames.","Season lamb chops and steaks with coarse salt and pepper only; season boerewors with nothing.","Grill boerewors as a whole coil 8–10 min per side, turning once with two forks.","Grill lamb chops 4–5 min per side; steaks 3 min per side for medium-rare. Rest 5 min.","Slice boerewors, plate with chops and steak.","Serve with hot pap and chakalaka. Drink: chilled Castle lager."]',
    'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=800&q=80',
    15, 30, 8, 'Medium', 'Main', 'South African',
    '{"South Africa","Southern Africa","BBQ","Heritage","Grill"}'),
  ('boerewors-south-africa',
    'South African coiled farmer''s sausage of beef and pork with coriander and clove.',
    'Descended from 17th-century Dutch verse worst, perfected on the Voortrekker Great Trek.',
    '["1.5 kg beef chuck","500 g pork belly","250 g beef or pork back fat","2 tbsp toasted coriander seed, ground","1 tsp ground clove","1 tsp ground nutmeg","1 tsp ground allspice","2 tbsp salt","1 tbsp black pepper","60 ml brown vinegar","60 ml ice water","3 m wide sausage casing"]',
    '["Cube meats and fat; chill in the freezer 30 min until firm.","Mince through a 6 mm plate. Mix with all spices, vinegar and ice water — knead 3 min until tacky.","Soak casing 30 min, rinse inside and out.","Stuff loosely (do not over-pack) and coil into a single spiral; tie ends.","Rest in the fridge overnight to bloom.","Grill over medium coals 8–10 min per side, turning once. Slice and serve in a hot-dog roll with chakalaka."]',
    'https://images.unsplash.com/photo-1601001435957-74f0958a93c5?w=800&q=80',
    60, 25, 10, 'Hard', 'Main', 'South African',
    '{"South Africa","Southern Africa","Sausage","Heritage","Grill"}'),
  ('biltong-south-africa',
    'South African air-dried, vinegar- and coriander-cured beef strips.',
    'Khoikhoi-origin preservation refined by Voortrekkers; air-cured, never smoked, unlike American jerky.',
    '["2 kg beef silverside, cut along the grain into 3 cm thick strips","250 ml brown vinegar","100 g coarse sea salt","60 g toasted coriander seed, coarsely ground","30 g black pepper","20 g brown sugar","Saltpetre (optional, pinch)"]',
    '["Mix coriander, salt, pepper and sugar.","Dip each beef strip briefly in vinegar; shake off excess.","Roll heavily in the spice mix to coat every surface.","Layer in a non-reactive dish; cure in the fridge 12 hours.","Rinse briefly in vinegar-water to remove surface salt; pat dry.","Hang on hooks in a cool, dry, well-ventilated box (a fan-cooled biltong box) for 4–7 days until dry on the outside, slightly springy in the middle.","Slice thin against the grain; store in cloth bags."]',
    'https://images.unsplash.com/photo-1606851179268-e34f29e2bdf7?w=800&q=80',
    30, 10080, 16, 'Medium', 'Snack', 'South African',
    '{"South Africa","Southern Africa","Cured","Beef","Snack"}'),
  ('vetkoek-south-africa',
    'South African fried yeasted dough cushions stuffed with curried mince or jam.',
    'A Voortrekker frontier bread that became the township breakfast staple of South Africa.',
    '["500 g bread flour","10 g instant yeast","1 tsp sugar","1 tsp salt","300 ml warm water","Vegetable oil for deep frying","FILLING: 500 g beef mince","1 onion, chopped","2 tbsp curry powder","1 tsp turmeric","1 tomato, grated","2 tbsp apricot jam","Salt"]',
    '["Mix flour, yeast, sugar and salt. Add water and knead 8 min into a soft dough.","Cover and prove 1 hour until doubled.","Sauté onion 5 min; add mince and brown. Stir in curry, turmeric, tomato, jam and salt; simmer 15 min.","Heat oil to 170°C. Pinch off lemon-sized dough balls, flatten slightly and fry 3–4 min per side until deep golden and hollow-sounding.","Drain on paper. Split open and stuff hot vetkoek with curried mince. Serve immediately."]',
    'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=800&q=80',
    75, 25, 8, 'Medium', 'Main', 'South African',
    '{"South Africa","Southern Africa","Fried","Bread","Township"}'),
  ('melktert-south-africa',
    'Cape Dutch silky cinnamon-dusted milk-and-egg custard tart.',
    'Adapted from the 17th-century Dutch mattentaart with Cape spice-route cinnamon.',
    '["CRUST: 250 g flour, 125 g butter cold, 60 g sugar, 1 egg, pinch salt","FILLING: 1 L full-cream milk","1 cinnamon stick","2 strips lemon zest","100 g sugar","60 g flour","30 g cornstarch","2 large eggs","2 tbsp butter","1 tsp vanilla","Ground cinnamon to dust"]',
    '["Rub butter into flour and sugar; bind with egg into a dough; chill 30 min.","Roll out, line a 24 cm tart tin, prick base, blind bake at 180°C for 15 min until pale gold.","Heat milk, cinnamon stick and lemon zest until almost boiling; remove zest and stick.","Whisk eggs, sugar, flour and cornstarch into a smooth paste; temper with hot milk, then return to the pan.","Cook gently, whisking, 4–5 min until thick. Off heat, beat in butter and vanilla.","Pour into the cooled crust; cool to room temperature, then chill 3 hours.","Dust generously with ground cinnamon before serving."]',
    'https://images.unsplash.com/photo-1571115764595-644a1f56a55c?w=800&q=80',
    30, 50, 8, 'Medium', 'Dessert', 'South African',
    '{"South Africa","Southern Africa","Cape Dutch","Custard","Tart"}'),
  ('kapenta-sadza-zambia',
    'Zambian sun-dried Lake Tanganyika sardines fried with tomato, served with stiff sadza.',
    'Lake Tanganyika and Kariba night-fishing under paraffin lamps is a cultural pillar of Zambia and Zimbabwe.',
    '["200 g dried kapenta (small sardines)","2 tomatoes, chopped","2 onions, sliced","4 garlic cloves","1 tsp paprika","2 tbsp vegetable oil","Salt","SADZA: 3 cups maize meal (mealie-meal)","4 cups water","Pinch of salt"]',
    '["Soak kapenta in warm water 10 min; drain and pat dry.","Heat oil; fry kapenta 4 min until crisp at the edges. Set aside.","In the same pan sauté onion 5 min, add garlic and tomato; cook 8 min into a thick relish; season with paprika and salt.","Return kapenta to the pan, toss to coat, simmer 3 min.","SADZA: bring 3 cups water to boil with salt. Whisk in 1 cup maize meal off the heat to make a slurry; cook 5 min.","Gradually add remaining maize meal, folding with a wooden mugiwo until very stiff; cook 8 min more, covered, on lowest heat.","Serve a mound of sadza with kapenta relish; eat with the right hand."]',
    'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?w=800&q=80',
    15, 30, 4, 'Medium', 'Main', 'Zambian',
    '{"Zambia","Zimbabwe","Southern Africa","Fish","Sadza"}')
) AS m(slug, summary, history, ingredients, steps, image_url, prep, cook, servings, difficulty, category, cuisine, tags)
